function norm(s){return String(s??'').trim().toUpperCase().replace(/,/g,'.').replace(/\s+/g,'');}
const {isReady,db}=require('./_db714');
async function dynamicKeys(ids){
 if(!isReady()||!ids.length)return {};
 const safe=ids.filter(id=>/^[\w-]{6,100}$/.test(id));if(!safe.length)return {};
 const filter=safe.map(x=>'\"'+x+'\"').join(',');
 const rows=await db('eduplan_question_additions?select=id,answer,explanation,content&status=eq.approved&id=in.('+encodeURIComponent(filter)+')');
 const out={};for(const r of rows){const ans=r.answer;
  out[r.id]={key:ans,kind:r.content?.kind,explanation:r.explanation||'Lời giải chưa được cung cấp.'};
 }return out;
}
function checkAnswer(value,key,kind){
 if(kind==='tf4'&&key&&typeof key==='object'){
  let v=value;try{if(typeof v==='string')v=v.trim().startsWith('{')?JSON.parse(v):Object.fromEntries(v.split(',').map((x,i)=>['abcd'[i],x.trim()]));}catch{return false;}
  return Boolean(v&&typeof v==='object'&&['a','b','c','d'].every(i=>norm(v[i])===norm(key[i])));
 }
 if(kind==='essay')return false; // Tự luận cần giáo viên chấm, không dùng so khớp chuỗi.
 return norm(value)===norm(key);
}
module.exports=async function handler(req,res){
 res.setHeader('Cache-Control','no-store');res.setHeader('X-Content-Type-Options','nosniff');
 if(req.method!=='POST')return res.status(405).json({error:'Method not allowed'});
 const qs=req.body?.questions;
 if(!Array.isArray(qs)||!qs.length||qs.length>50)return res.status(400).json({error:'Expected 1-50 questions'});
 const used=new Set(),results=[];let checked=0,correct=0;
 let cloud={};try{cloud=await dynamicKeys(qs.map(x=>x?.id).filter(id=>id&&!KEYS[id]));}
 catch(err){console.warn('Extra bank lookup unavailable:',err.message);}
 for(const q of qs){
  if(typeof q?.id!=='string'||q.id.length>80||used.has(q.id)||typeof q.answer!=='string'||q.answer.length>5000)return res.status(400).json({error:'Invalid answer payload'});
  used.add(q.id);const k=KEYS[q.id]||cloud[q.id];
  if(!k){results.push({id:q.id,status:'unverified'});continue;}
  const ok=checkAnswer(q.answer,k.key,k.kind);if(k.kind!=='essay'){checked++;if(ok)correct++;}
  results.push(k.kind==='essay'?{id:q.id,status:'teacher_review',correctAnswer:k.key,explanation:k.explanation}:{id:q.id,status:'checked',correct:ok,correctAnswer:k.key,explanation:k.explanation});
 }
 res.status(200).json({checked,correct,total:qs.length,results,note:'Self-practice feedback only; no authenticated exam session.'});
};
